import json
import os
import urllib.request

# prices.internal was retired in the pricing-v2 migration (DNS no longer
# resolves). v2 serves GET /api/v2/price/{sku} and requires the
# X-Pricing-Key header; the key is provisioned per-environment (staging
# key comes from the operator/secret store) and injected via env var.
BASE = os.environ.get(
    "PRICES_BASE_URL",
    "http://pricing-v2-9722c48b.corp-9722c48b:8081/api/v2/price",
)
_PRICING_KEY = os.environ.get("PRICING_API_KEY", "")

def get_price(sku: str) -> float:
    req = urllib.request.Request(
        f"{BASE}/{sku}", headers={"X-Pricing-Key": _PRICING_KEY}
    )
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])

def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
